def deprecation_headers(sunset_date: str) -> dict:
    return {
        "Deprecation": "true",
        "Sunset": sunset_date,
        "Link": '<https://developer.acme.example/migrate>; rel="deprecation"',
    }

import unittest

from api.headers import deprecation_headers


class DeprecationHeadersTests(unittest.TestCase):
    def test_exact_guideline_headers(self):
        sunset_date = "Wed, 01 Jan 2025 00:00:00 GMT"
        self.assertEqual(
            deprecation_headers(sunset_date),
            {
                "Deprecation": "true",
                "Sunset": sunset_date,
                "Link": '<https://developer.acme.example/migrate>; rel="deprecation"',
            },
        )

    def test_sunset_uses_supplied_http_date(self):
        sunset_date = "Thu, 31 Dec 2026 23:59:59 GMT"
        self.assertEqual(deprecation_headers(sunset_date)["Sunset"], sunset_date)

    def test_results_are_independent(self):
        sunset_date = "Thu, 31 Dec 2026 23:59:59 GMT"
        headers = deprecation_headers(sunset_date)
        headers["Deprecation"] = "false"
        self.assertEqual(deprecation_headers(sunset_date)["Deprecation"], "true")


if __name__ == "__main__":
    unittest.main()
